import datetime
import re

from ta_moler.events.rtg.genericrtg_lineevent import GenericRtgLineEvent


class SectorNotReceivingOvhd(GenericRtgLineEvent):
    """Sector not receiving OVHD event class."""

    # Example line:
    # Executor: ERROR: SECTOR-9@9 is not receiving OVHD (MIB/SIB). Cell is temporary excluded from scheduling new UEs
    re_sector_not_receiving_ovhd = re.compile(r"ERROR:\s+(?P<SECTOR>SECTOR-.*) is not receiving OVHD \(MIB/SIB\)")
    # Example line:
    # Connection Manager: Sectors Cleanup: SECTOR-13@13 is not receiving overhead messages
    re_sector_not_receiving_overhead_messages = re.compile(
        r"(?P<SECTOR>SECTOR-.*) is not receiving overhead(:? BR)? messages")
    re_some_sector_not_receiving_overhead_messages = re.compile(
        r"Some cells don't receive OVHD \(MIB/SIB\) messages")

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for sector not receiving ovhd.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(SectorNotReceivingOvhd, self).__init__(
            connection=connection,
            runner=runner,
            till_occurs_times=till_occurs_times,
            detect_patterns=[
                self.re_sector_not_receiving_ovhd,
                self.re_sector_not_receiving_overhead_messages,
                self.re_some_sector_not_receiving_overhead_messages
            ],
            match="any",
        )


EVENT_OUTPUT = """
Executor: ERROR: SECTOR-9@9 is not receiving OVHD (MIB/SIB). Cell is temporary excluded from scheduling new UEs"""

EVENT_KWARGS = {"till_occurs_times": 1}

EVENT_RESULT = [
    {
        "groups": ("SECTOR-9@9",),
        "line": "Executor: ERROR: SECTOR-9@9 is not receiving OVHD (MIB/SIB). " "Cell is temporary excluded from scheduling new UEs",
        "matched": "ERROR: SECTOR-9@9 is not receiving OVHD (MIB/SIB)",
        "named_groups": {"SECTOR": "SECTOR-9@9"},
        "time": datetime.datetime.now(),
    }
]
